def cross_card_consistency(datacard, modelcard, systemcard, protocol):
    befunde = []
    namen = {datacard.get("name"), modelcard.get("trainingsdaten"), protocol.get("datensatz")}
    if len(namen) > 1:
        befunde.append("datensatz-unstimmig")
    metriken = {datacard.get("metrik"), modelcard.get("metrik"), systemcard.get("metrik"), protocol.get("metrik")}
